# Transcrição das duas páginas da Lista 9 (2026). As anotações manuscritas não fazem parte dos enunciados.
E=[]
def add(title,q,choices,steps,answer,kind,base,unit='cm'):
 E.append(dict(id=len(E)+1,title=title,q=q,choices=choices,steps=steps,answer=answer,kind=kind,base=base,unit=unit))
add('Do raio ao segmento de tangência',r'(PUC-MG) O triângulo ABC é equilátero e está circunscrito ao círculo de centro O e raio 2 cm. AD é a altura do triângulo. Sendo E o ponto de tangência no lado AC, determine AE, em centímetros.',[r'$2\sqrt3$',r'$2\sqrt5$','3','5',r'$\sqrt{26}$'],[r'O círculo está dentro do triângulo; seu raio é o apótema: $r=2$.',r'No equilátero, $h=3r=6$ e $AO=2r=4$. O raio $OE=2$ é perpendicular a AC.',r'No triângulo retângulo AOE: $AE^2=AO^2-OE^2=4^2-2^2=12$.',r'$AE=\sqrt{12}=2\sqrt3\,\mathrm{cm}$. Alternativa A.'],r'$AE=2\sqrt3\,\mathrm{cm}$','tangent',2)
add('Raio do círculo circunscrito',r'(UNIFESP) Um triângulo equilátero tem lado 6 cm. Qual é o raio do círculo circunscrito a esse triângulo, em centímetros?',[r'$\sqrt3$',r'$2\sqrt3$','4',r'$3\sqrt2$',r'$3\sqrt3$'],[r'O círculo passa pelos três vértices: queremos o raio circunscrito R.',r'A altura divide o lado ao meio: $h^2=6^2-3^2=27$, então $h=3\sqrt3$.',r'O centro divide a altura na razão 2:1: $R=\frac23h$.',r'$R=\frac23\cdot3\sqrt3=2\sqrt3\,\mathrm{cm}$. Alternativa B.'],r'$R=2\sqrt3\,\mathrm{cm}$','triangle-in',6)
add('Apótema do hexágono',r'O apótema de um hexágono regular inscrito numa circunferência de raio 8 cm vale, em centímetros:', ['4',r'$4\sqrt3$','8',r'$8\sqrt2$','12'],[r'O raio do círculo é $R=8$. Cada triângulo central do hexágono é equilátero, logo o lado também mede 8.',r'O apótema liga o centro ao ponto médio de um lado. Metade do lado mede 4.',r'No triângulo retângulo: $a^2=8^2-4^2=48$.',r'$a=\sqrt{48}=4\sqrt3\,\mathrm{cm}$. Alternativa B.'],r'$a=4\sqrt3\,\mathrm{cm}$','hex-in',8)
add('Duas figuras, a mesma circunferência',r'(FGV) O lado de um quadrado inscrito em um círculo mede $12\sqrt2\,\mathrm{m}$. Qual é o lado do triângulo equilátero circunscrito ao mesmo círculo?', [r'$20\sqrt3\,\mathrm{m}$',r'$20\sqrt5\,\mathrm{m}$',r'$24\sqrt5\,\mathrm{m}$',r'$24\sqrt3\,\mathrm{m}$',r'$40\,\mathrm{m}$'],[r'A diagonal do quadrado inscrito é o diâmetro do círculo.',r'$2R=(12\sqrt2)\sqrt2=24$, portanto $R=12\,\mathrm{m}$.',r'Esse mesmo raio é o apótema do triângulo circunscrito: $r=R=12$. O lado é $L=2r\sqrt3$.',r'$L=24\sqrt3\,\mathrm{m}$. Alternativa D.'],r'$L=24\sqrt3\,\mathrm{m}$','square-in-triangle-out',12,'m')
add('Razão entre as alturas',r'(UNIFESP) Numa circunferência de raio $R>0$, considere os triângulos equiláteros T₁, inscrito, e T₂, circunscrito, conforme a figura. Qual é a razão entre a altura de T₂ e a altura de T₁?', ['4','3',r'$5/2$',r'$2\pi/3$','2'],[r'Em T₁, o raio circunscrito é R. A altura vale $h_1=\frac32R$.',r'Em T₂, o raio inscrito é R. A altura vale $h_2=3R$.',r'Divida as alturas na ordem pedida: $\frac{h_2}{h_1}=\frac{3R}{3R/2}$.',r'A razão é 2, independente de R. Alternativa E.'],'$h_2/h_1=2$','two-triangles',1,'unidades')
add('Dois círculos tangentes',r'(ITA) Uma circunferência C₁, de raio R₁, está inscrita em um triângulo equilátero de altura h. Uma segunda circunferência C₂, de raio R₂, tangencia dois lados do triângulo internamente e C₁ externamente. Calcule $(R_1-R_2)/h$.',[],[r'O círculo maior é a incircunferência do equilátero: $R_1=h/3$. Seu centro está a $2R_1$ do vértice A.',r'O centro do círculo menor está a $2R_2$ de A. Assim, a distância entre os centros é $2R_1-2R_2$.',r'Como os círculos são tangentes externamente, $2R_1-2R_2=R_1+R_2$. Portanto, $R_1=3R_2$ e $R_2=h/9$.',r'$\frac{R_1-R_2}{h}=\frac{h/3-h/9}{h}=\frac29$.'],r'$(R_1-R_2)/h=2/9$','two-circles',9,'unidades')
add('Paralelas e tangência',r'Com os dados da figura, determine x. As retas r, m e s são paralelas; m está 10 unidades acima de s. O círculo tem raio 6, tangencia r e os dois lados inclinados que formam ângulos de 60° com s. x é a distância entre r e m.',[],[r'O ângulo entre os lados inclinados é $180°-60°-60°=60°$. A linha entre o vértice e o centro divide esse ângulo em 30°.',r'O raio 6 é perpendicular ao lado. No triângulo retângulo, $\sin30°=6/d$, logo a distância do vértice ao centro é $d=12$.',r'Do vértice à reta r, a distância é $12+6=18$. Como m está 10 acima de s, temos $x+10=18$.',r'$x=8$.'],r'$x=8$','parallel',6,'unidades')
add('Quadrados inscrito e circunscrito',r'(UFF-RJ) Qual é a razão entre o lado do quadrado inscrito e o lado do quadrado circunscrito a uma circunferência de raio R?', [r'$1/3$',r'$1/2$',r'$\sqrt3/3$',r'$\sqrt2/2$',r'$\sqrt2$'],[r'No quadrado inscrito, a diagonal mede 2R. Como a diagonal vale $l_i\sqrt2$, temos $l_i=R\sqrt2$.',r'No quadrado circunscrito, a distância entre lados opostos é o diâmetro: $l_c=2R$.',r'$\frac{l_i}{l_c}=\frac{R\sqrt2}{2R}$.',r'A razão é $\sqrt2/2$. Alternativa D.'],r'$l_i/l_c=\sqrt2/2$','two-squares',1,'unidades')
add('Hexágono dos pontos médios',r'(FGV, modificada) Os pontos médios dos lados do hexágono regular ABCDEF são os vértices do hexágono menor MNPQRS. Se o lado do hexágono maior mede 4 cm, quanto mede o lado do hexágono menor?', [r'$2\sqrt3$',r'$\sqrt3$','3','4',r'$2\sqrt3/3$'],[r'Um lado do hexágono menor liga os pontos médios de dois lados consecutivos do maior.',r'No triângulo formado por três vértices consecutivos, esse segmento médio mede metade da diagonal menor do hexágono maior.',r'Essa diagonal mede $4\sqrt3$, pois $d^2=4^2+4^2-2\cdot4\cdot4\cos120°=48$.',r'O lado menor é $d/2=2\sqrt3\,\mathrm{cm}$. Alternativa A.'],r'$l=2\sqrt3\,\mathrm{cm}$','midpoints',4)
add('Triângulo inscrito e quadrado externo',r'(UFSC, modificada) Se o lado do triângulo equilátero inscrito na circunferência mede $6\sqrt3\,\mathrm{cm}$, qual é o lado do quadrado circunscrito à circunferência?', ['8 cm',r'$9\sqrt3\,\mathrm{cm}$',r'$12\sqrt3\,\mathrm{cm}$','12 cm','15 cm'],[r'No triângulo equilátero inscrito, o lado vale $L=R\sqrt3$.',r'$R=\frac{6\sqrt3}{\sqrt3}=6\,\mathrm{cm}$.',r'O lado do quadrado externo é o diâmetro: $l=2R$.',r'$l=12\,\mathrm{cm}$. Alternativa D.'],r'$l=12\,\mathrm{cm}$','triangle-in-square-out',6)
add('Perímetro do quadrado externo',r'Um triângulo equilátero e um quadrado estão circunscritos à mesma circunferência. Se o lado desse triângulo mede $2\sqrt3$, qual é o perímetro do quadrado?', ['2','4',r'$4\sqrt3$','8',r'$8\sqrt3$'],[r'O círculo é interno às duas figuras. No equilátero, $L=2r\sqrt3$.',r'$2\sqrt3=2r\sqrt3$, portanto $r=1$.',r'O lado do quadrado é $2r=2$. Seu perímetro é quatro vezes o lado.',r'$P=4\cdot2=8$. Alternativa D.'],'$P=8$','triangle-out-square-out',1,'unidades')
add('Hexágono circunscrito',r'(UEL) Um círculo de raio 5 cm está inscrito em um hexágono regular. Qual é o perímetro do hexágono, em centímetros?', [r'$20\sqrt3$',r'$18\sqrt3$',r'$15\sqrt2$',r'$12\sqrt3$',r'$9\sqrt2$'],[r'O raio do círculo é o apótema do hexágono: $a=5$.',r'Para um hexágono regular, $a=\frac{l\sqrt3}{2}$. Logo, $l=\frac{2a}{\sqrt3}=\frac{10\sqrt3}{3}$.',r'O perímetro tem seis lados: $P=6l=6\cdot\frac{10\sqrt3}{3}$.',r'$P=20\sqrt3\,\mathrm{cm}$. Alternativa A.'],r'$P=20\sqrt3\,\mathrm{cm}$','hex-out',5)
add('Um lado tangente, dois vértices na circunferência',r'(UFPR, modificada) Uma circunferência de raio 5 cm tangencia um lado de um quadrado e passa pelos dois vértices que não pertencem a esse lado, conforme a figura. Qual é o perímetro do quadrado, em centímetros?', ['16','20','24','32','36'],[r'Seja l o lado. A reta do lado tangente está a R=5 do centro. Os vértices opostos têm deslocamento horizontal l/2 e deslocamento vertical de módulo |l−5|.',r'Um raio até um desses vértices dá $\left(\frac l2\right)^2+(l-5)^2=25$.',r'$\frac54l^2-10l=0$, ou $l(5l-40)=0$. Descarte l=0: $l=8$.',r'O perímetro é $P=4l=32\,\mathrm{cm}$. Alternativa D.'],r'$P=32\,\mathrm{cm}$','tangent-square',5)
add('Distância entre torres',r'(UFF-RJ) Torres de transmissão estão nos centros de hexágonos regulares congruentes, justapostos e inscritos em círculos. Na figura, o raio de cada círculo é 1 km. Determine, respectivamente, as distâncias $d_{3,8}$, $d_{3,5}$ e $d_{5,8}$, entre as torres indicadas.',[r'$2\sqrt3;\ 3;\ 3+2\sqrt3$',r'$4;\ 3;\ 5$',r'$4;\ 3\sqrt3/2;\ 4+3\sqrt3/2$',r'$2\sqrt3;\ 3;\ \sqrt{21}$',r'$4;\ 3\sqrt3/2;\ 9/2$'],[r'Cada hexágono tem lado R=1 e apótema $\sqrt3/2$. Centros de células vizinhas ficam a $\sqrt3$ km.',r'Com a torre 1 na origem, podemos usar $3=(0,\sqrt3)$, $5=(-3/2,-\sqrt3/2)$ e $8=(3,0)$.',r'Pelo teorema de Pitágoras: $d_{3,8}^2=3^2+(\sqrt3)^2=12$; $d_{3,5}^2=(3/2)^2+(3\sqrt3/2)^2=9$.',r'Também $d_{5,8}^2=(9/2)^2+(\sqrt3/2)^2=21$. Portanto, as distâncias são $2\sqrt3$, 3 e $\sqrt{21}$ km. Alternativa D.'],r'$d_{3,8}=2\sqrt3;\ d_{3,5}=3;\ d_{5,8}=\sqrt{21}\,\mathrm{km}$','towers',1,'km')
assert len(E)==14 and all(len(e['steps'])==4 for e in E)
